# Example for page "main": draw once, then update in a loop.
# Generated by ESP UI Builder; replace the demo part with your own code.

import time

import ui_display
import ui_main

ui = ui_main.UI(ui_display.create())
p = dict(ui_main.DEFAULTS)
ui.draw(p)

# Animations run from ui.tick() (non-blocking, ~every 10 ms); parameters change once a second.
last = time.ticks_ms()
while True:
    ui.tick()
    if time.ticks_diff(time.ticks_ms(), last) >= 1000:
        last = time.ticks_ms()
        # Change p[...] here, then:
        ui.update(p)
    time.sleep_ms(10)
